// One shared no-code panel for the native sequence and reusable catalog variants.
import {hybridDefaults} from './hybrid-scene.js?v=motion-v70';
import {stagingDefaults} from './reference-staging.js?v=motion-v70';
const quickDefaults={...stagingDefaults,...hybridDefaults};
export function mountReferenceControls(host,p,{save=()=>{},replace=()=>{},preview=()=>{},images}={}){const el=(tag,text)=>{const e=document.createElement(tag);if(text)e.textContent=text;return e},button=(where,label,run)=>{const b=el('button',label);b.className='pill';b.onclick=run;where.append(b);return b},slider=(where,key,label,min,max,step)=>{const row=el('label'),name=el('span',label),out=el('output',String(p[key]??quickDefaults[key])),input=el('input');input.type='range';input.min=min;input.max=max;input.step=step;input.value=p[key]??quickDefaults[key];input.setAttribute('aria-label',label);input.oninput=()=>{p[key]=Number(input.value);out.textContent=input.value;save()};row.append(name,input,out);where.append(row);return input};
const toggle=(where,key,label,fallback=true)=>{const b=button(where,'',()=>{p[key]=!(p[key]??fallback);b.textContent=label+': '+(p[key]?'On':'Off');save()});b.textContent=label+': '+((p[key]??fallback)?'On':'Off');return b};const title=el('p','1. Choose a scene. 2. Replace an item. 3. Adjust its size or timing.'),select=el('select');select.setAttribute('aria-label','Scene to edit');for(const [value,label]of [['room','Paper, mother and boy'],['street','War street and electrical collapse']]){const o=el('option',label);o.value=value;select.append(o)}host.append(title,select);const room=el('div'),street=el('div');host.append(room,street);street.hidden=true;select.onchange=()=>{room.hidden=select.value!=='room';street.hidden=select.value!=='street';preview(select.value==='room'?5.5:16)};
for(const [slot,label]of [['stagingRoom','room and window'],['stagingShelf','wooden shelf'],['continuationBoyColor','boy'],['historyMotherPerson','mother'],['historyRoomVase','basin'],['historyRoomCloth','sill cloth']])button(room,'Replace '+label+'…',()=>replace(slot));
for(const [t,label]of [[2,'See paper'],[4.4,'See overlap'],[6,'See boy']])button(room,label,()=>preview(t));
slider(room,'stagingMatWidth','Gray frame width',0,90,1);slider(room,'stagingBoyWidth','Boy size',250,900,5);slider(room,'stagingBoyX','Boy left / right',-100,700,5);slider(room,'stagingBoyY','Boy up / down',-150,350,5);slider(room,'stagingRoomPush','Camera zoom amount',0,1.3,.01);slider(room,'stagingShelfX','Shelf left / right',400,1000,5);slider(room,'stagingShelfWidth','Shelf size',80,350,5);
button(room,'Toggle previous room layout',()=>{p.stagingRoomEnabled=!p.stagingRoomEnabled;save()});const rd=el('details');rd.append(el('summary','More placement, color and timing'));room.append(rd);const colorLabel=el('label','Gray frame color'),color=el('input');color.type='color';color.value=p.stagingMatColor||stagingDefaults.stagingMatColor;color.setAttribute('aria-label','Gray frame color');color.oninput=()=>{p.stagingMatColor=color.value;save()};colorLabel.append(color);rd.append(colorLabel);for(const a of [['stagingColorStart','Color starts (clip seconds)',0,10,.05],['stagingColorEnd','Color finishes',.1,12,.05],['stagingMotherExitStart','Mother starts leaving',0,10,.05],['stagingMotherExitEnd','Mother is gone',.1,12,.05],['stagingBoyStart','Boy starts appearing',0,10,.05],['stagingBoyEnd','Boy is fully visible',.1,12,.05],['stagingRoomLight','Room brightness',.3,1.3,.01],['stagingRoomFocusX','Zoom focus left / right',0,1,.01],['stagingRoomFocusY','Zoom focus up / down',0,1,.01],['stagingShelfLight','Shelf brightness',.2,1.3,.01],['stagingBoyLight','Boy brightness',.3,1.3,.01],['stagingFaceShadow','Boy shadow on right',0,.65,.01],['stagingBoyDepth','Boy depth response',.5,3,.1],['stagingBasinDepth','Basin foreground depth',.5,4,.1],['stagingShelfDepth','Shelf depth response',.5,2,.1],['stagingMotherX','Mother left / right',0,900,5],['stagingMotherY','Mother up / down',-150,400,5],['stagingMotherWidth','Mother size',100,700,5],['stagingShelfY','Shelf up / down',0,500,5],['stagingBasinX','Basin left / right',-500,500,5],['stagingBasinY','Basin up / down',0,650,5],['stagingBasinWidth','Basin size',100,900,5],['stagingClothX','Sill cloth left / right',0,700,5],['stagingClothY','Sill cloth up / down',0,500,5],['stagingClothWidth','Sill cloth size',30,300,5]])slider(rd,...a);
for(const [slot,label]of [['stagingStreet','street and road'],['stagingSoldier','back-view person'],['streetExplosion','explosion']])button(street,'Replace '+label+'…',()=>replace(slot));for(const [t,label]of [[13.6,'See entrance'],[16,'See explosion'],[18,'See collapse'],[24,'See camera push']])button(street,label,()=>preview(t));
for(const a of [['hybridTravel','Camera approach',0,6,.05],['stagingStreetLight','Street brightness',.25,1.2,.01],['hybridActorHeight','Person size',1,2.5,.02],['hybridActorDepth','Person forward / back',5,10,.1],['hybridActorX','Person left / right',-3,3,.05],['hybridWireRelease','Wires start falling',11,20,.05],['hybridWireFallTime','Fall duration (seconds)',.4,12,.1],['stagingSparkSize','Spark size',.3,3,.1]])slider(street,...a);
button(street,'Toggle dark window interiors',()=>{p.stagingFillInteriors=!p.stagingFillInteriors;save()});toggle(street,'expansionTowerOnly','Isolated broken wall');toggle(street,'hybridStreetEnabled','Shared depth camera');toggle(street,'hybridSalvageAttach','Cables attached to ruin');toggle(street,'groundedWalkEnabled','Photographic foot ground contact');button(street,'Toggle previous modeled street',()=>{p.stagingStreetEnabled=!p.stagingStreetEnabled;save()});const sd=el('details');sd.append(el('summary','More smoke, poles and sparks'));street.append(sd);for(const a of [['stagingStreetReveal','Dark entrance duration',.3,4,.1],['hybridForegroundDepth','Foreground building depth',6,18,.1],['hybridCameraHeight','Shared camera height',1.4,2.8,.02],['hybridFocal','Shared lens focal amount',600,1000,10],['hybridHorizonEnd','Final vertical framing',-50,220,5],['hybridActorTrack','Keep person in frame',0,1,.05],['hybridActorEndX','Person final screen position',400,850,5],['hybridWireNearDepth','Fallen wires depth',6,15,.1],['walkFrontArmFactor','Near arm movement',0,2,.05],['walkBackArmFactor','Torch arm movement',0,2,.05],['hybridPan','Late sideways camera travel',0,4.5,.05],['hybridPanStart','Sideways move starts',20,26,.1],['hybridPanDuration','Sideways move duration',.5,4,.1],['hybridWireWidth','Wire thickness',.4,4,.05],['hybridWireSag','Wire sag',0,1,.02],['hybridWalkTravel','Walker travel speed',.5,2,.05],['hybridWalkCadence','Walker step pace',.5,1.8,.05],['expansionRuinAlphaCutoff','Clean ruin edge',0,254,1],['expansionTerrainRelief','Uneven terrain',0,.3,.01],['hybridSalvageSkyLight','Salvage sky brightness',.3,1,.02],['hybridRuinAnchorU','Ruin cable attachment left / right',.6,1,.01],['hybridRuinAnchorV','Ruin cable attachment up / down',0,.5,.01],['hybridCableReach','Cable reach to offscreen support',2,10,.1],['stagingStreetFocusX','Zoom focus left / right',0,1,.01],['stagingStreetFocusY','Zoom focus up / down',0,1,.01],['stagingForegroundStrength','Foreground debris',0,1,.05],['stagingStreetPersonGrowth','Person growth during zoom',0,400,5],['stagingStreetPersonLight','Person brightness',.3,1.2,.01],['stagingPoleLean','Pole fall angle',0,80,1],['stagingElectricalDepth','Electrical structure size',.4,1.7,.01],['stagingSparkCount','Sparks per burst',0,40,1],['stagingSparkLifetime','Spark lifetime (seconds)',.04,.3,.01],['stagingSparkStop','All sparks stop by',14,25,.05],['stagingSmokeOpacity','Smoke opacity',0,1,.01]])slider(sd,...a);
mountAttachmentPicker(street,p,images,save);button(host,'Reset these scene settings',()=>{const keys=select.value==='room'?Object.keys(quickDefaults).filter(k=>k.startsWith('staging')&&!/^staging(Street|Pole|Failure|Spark|Electrical|Smoke|Foreground|Fill)/.test(k)):Object.keys(quickDefaults).filter(k=>k.startsWith('hybrid')||/^staging(Street|Pole|Failure|Spark|Electrical|Smoke|Foreground|Fill)/.test(k));for(const k of keys)p[k]=structuredClone(quickDefaults[k]);save();host.replaceChildren();mountReferenceControls(host,p,{save,replace,preview,images});});return {select,room,street};}

function snapWallAttachment(im,u,v){if(!(im?.naturalWidth||im?.width))return [u,v];const W=im.naturalWidth||im.width,H=im.naturalHeight||im.height,cv=Object.assign(document.createElement('canvas'),{width:W,height:H}),c=cv.getContext('2d');c.drawImage(im,0,0);const a=c.getImageData(0,0,W,H).data,x=Math.min(W-1,Math.floor(u*W)),y=Math.min(H-1,Math.floor(v*H));if(a[(y*W+x)*4+3]>180)return[u,v];let best=Infinity,point=[u,v];for(let Y=0;Y<H;Y++)for(let X=0;X<W;X++){if(a[(Y*W+X)*4+3]<220)continue;const d=((X/W-u)*480)**2+((Y/H-v)*270)**2;if(d<best){best=d;point=[(X+.5)/W,(Y+.5)/H];}}return point;}
function mountAttachmentPicker(host,p,images,save){if(!images)return;const details=document.createElement('details');details.innerHTML='<summary>Point to cable attachments</summary>';host.append(details);const note=document.createElement('p');note.textContent='Choose an attachment, then tap the picture. Its marker stays with the surface as the camera moves. Empty sky or window holes snap to the nearest solid wall pixel.';details.append(note);const select=document.createElement('select');select.setAttribute('aria-label','Cable attachment to place');for(const [value,label]of [['left','Street left attachment'],['right','Street right attachment'],['ruin','Salvage wall attachment']]){const o=document.createElement('option');o.value=value;o.textContent=label;select.append(o);}details.append(select);const canvas=document.createElement('canvas');canvas.width=480;canvas.height=270;canvas.style.width='100%';canvas.style.maxWidth='480px';canvas.style.touchAction='none';canvas.setAttribute('aria-label','Tap picture to place cable attachment');details.append(canvas);const paint=()=>{const im=select.value==='ruin'?images.salvageRuins:images[p.historySourceBindings?.stagingStreet||'stagingStreet'],c=canvas.getContext('2d');if(!c)return;c.clearRect(0,0,480,270);c.fillStyle='#24242a';c.fillRect(0,0,480,270);if(im&&(im.naturalWidth||im.width))c.drawImage(im,0,0,480,270);const entries=select.value==='ruin'?[['ruin',[p.hybridRuinAnchorU??.92,p.hybridRuinAnchorV??.14]]]:Object.entries(p.hybridWireAnchors||hybridDefaults.hybridWireAnchors);for(const [key,v]of entries){c.strokeStyle=key==='left'?'#42b8ff':'#ffcc55';c.lineWidth=3;c.beginPath();c.arc(v[0]*480,v[1]*270,7,0,Math.PI*2);c.stroke();}};canvas.onpointerdown=e=>{const r=canvas.getBoundingClientRect();let u=Math.max(0,Math.min(1,(e.clientX-r.left)/r.width)),v=Math.max(0,Math.min(1,(e.clientY-r.top)/r.height));if(select.value==='ruin'){[u,v]=snapWallAttachment(images.salvageRuins,u,v);p.hybridRuinAnchorU=u;p.hybridRuinAnchorV=v;p.hybridSalvageAttach=true;}else{p.hybridWireAnchors=structuredClone(p.hybridWireAnchors||hybridDefaults.hybridWireAnchors);p.hybridWireAnchors[select.value||'left']=[u,v];}save();paint();};select.onchange=paint;details.addEventListener?.('toggle',paint);for(const im of [images.stagingStreet,images.salvageRuins])im?.addEventListener?.('load',paint,{once:true});paint();}
